export interface Song {
  title: string;
  artist: string;
  genre: string;
  description: string;
  youtubeQuery: string;
}

export interface CulturalData {
  countryName: string;
  summary: string;
  traditions: string[];
  musicalStyles: string[];
  songs: Song[];
}

export interface GeoJsonProperties {
  ADMIN: string;
  ISO_A3: string;
}

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { CulturalData } from "../types";

// Initialize Gemini client
// Note: In a real app, ensure process.env.API_KEY is defined.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

const schema: Schema = {
  type: Type.OBJECT,
  properties: {
    countryName: { type: Type.STRING, description: "El nombre del país en español." },
    summary: { type: Type.STRING, description: "Un resumen breve (aprox 80 palabras) sobre la historia musical y cultural del país." },
    traditions: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "Lista de 3 a 5 tradiciones culturales importantes conectadas con la música o danza."
    },
    musicalStyles: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "Lista de 3 a 5 géneros musicales históricos o folclóricos."
    },
    songs: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          artist: { type: Type.STRING },
          genre: { type: Type.STRING },
          description: { type: Type.STRING, description: "Breve explicación de por qué es importante." },
          youtubeQuery: { type: Type.STRING, description: "Término de búsqueda optimizado para encontrar esta canción en YouTube." }
        },
        required: ["title", "artist", "genre", "description", "youtubeQuery"]
      },
      description: "Lista de 3 canciones icónicas, históricas o tradicionales."
    }
  },
  required: ["countryName", "summary", "traditions", "musicalStyles", "songs"]
};

export const fetchCountryData = async (countryName: string): Promise<CulturalData | null> => {
  try {
    const model = "gemini-3-flash-preview";
    const prompt = `
      Actúa como un etnomusicólogo experto e historiador cultural.
      El usuario ha seleccionado el país: "${countryName}".

      Proporciona información detallada sobre la música histórica, folclórica y tradicional de este país.
      Conecta la música con sus tradiciones, provincias, territorios y raíces históricas.

      Responde EXCLUSIVAMENTE en formato JSON válido siguiendo el esquema proporcionado.
      El idioma de la respuesta debe ser ESPAÑOL.
    `;

    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: schema,
        systemInstruction: "Eres un experto en música del mundo y cultura. Tu objetivo es educar sobre la riqueza musical de cada nación.",
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as CulturalData;
    }

    return null;
  } catch (error) {
    console.error("Error fetching data from Gemini:", error);
    return null;
  }
};

