import React, { useEffect, useRef, useState, useCallback } from 'react';
import Globe, { GlobeMethods } from 'react-globe.gl';
import { GeoJsonProperties } from '../types';

interface EarthGlobeProps {
  onCountryClick: (properties: GeoJsonProperties) => void;
}

export const EarthGlobe: React.FC<EarthGlobeProps> = ({ onCountryClick }) => {
  const globeEl = useRef<GlobeMethods | undefined>(undefined);
  const [hoverD, setHoverD] = useState<object | null>(null);
  const [countries, setCountries] = useState({ features: [] });
  const [width, setWidth] = useState(window.innerWidth);
  const [height, setHeight] = useState(window.innerHeight);

  useEffect(() => {
    // Responsive globe
    const handleResize = () => {
      setWidth(window.innerWidth);
      setHeight(window.innerHeight);
    };
    window.addEventListener('resize', handleResize);

    // Load GeoJSON data
    fetch('https://raw.githubusercontent.com/vasturiano/react-globe.gl/master/example/datasets/ne_110m_admin_0_countries.geojson')
      .then(res => res.json())
      .then(setCountries)
      .catch(err => console.error("Error loading globe data:", err));

    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // Set initial point of view
  useEffect(() => {
    if (globeEl.current) {
      globeEl.current.pointOfView({ lat: 20, lng: 0, altitude: 2.0 });
      // Auto-rotate
      globeEl.current.controls().autoRotate = true;
      globeEl.current.controls().autoRotateSpeed = 0.5;
    }
  }, [globeEl.current]);

  const handlePolygonClick = useCallback((polygon: object) => {
    const p = polygon as { properties: GeoJsonProperties, bbox?: number[] };

    // Stop rotation on interaction
    if (globeEl.current) {
        globeEl.current.controls().autoRotate = false;

        // Use polygon centroid to zoom in (approximate via react-globe.gl internal utils or bbox if available)
        // Simplification: We zoom to the clicked point on the surface (handled by the interaction event mostly)
        // But for better UX, we can compute centroid. 
        // For this demo, we let the user manually zoom or we could implement bbox calculation.
        // Let's just focus on the data fetching trigger.
    }

    onCountryClick(p.properties);
  }, [onCountryClick]);

  return (
    <div className="cursor-move">
      <Globe
        ref={globeEl}
        width={width}
        height={height}
        globeImageUrl="//unpkg.com/three-globe/example/img/earth-blue-marble.jpg"
        backgroundImageUrl="//unpkg.com/three-globe/example/img/night-sky.png"

        polygonsData={countries.features}
        polygonAltitude={d => d === hoverD ? 0.12 : 0.06}
        polygonCapColor={d => d === hoverD ? 'rgba(100, 200, 255, 0.4)' : 'rgba(200, 200, 200, 0.0)'}
        polygonSideColor={() => 'rgba(255, 255, 255, 0.1)'}
        polygonStrokeColor={() => '#111'}
        polygonLabel={({ properties: d }: any) => `
          <div class="bg-black/80 text-white px-2 py-1 rounded text-xs font-mono border border-white/20">
            ${d.ADMIN} (${d.ISO_A3})
          </div>
        `}
        onPolygonHover={setHoverD}
        onPolygonClick={handlePolygonClick}

        atmosphereColor="#3a228a"
        atmosphereAltitude={0.2}
      />
    </div>
  );
};

import React, { useState, useCallback } from 'react';
import { EarthGlobe } from './components/EarthGlobe';
import { InfoPanel } from './components/InfoPanel';
import { fetchCountryData } from './services/geminiService';
import { CulturalData, GeoJsonProperties } from './types';
import { Music2 } from 'lucide-react';

const App: React.FC = () => {
  const [selectedCountry, setSelectedCountry] = useState<string | null>(null);
  const [culturalData, setCulturalData] = useState<CulturalData | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isPanelOpen, setIsPanelOpen] = useState(false);

  const handleCountryClick = useCallback(async (properties: GeoJsonProperties) => {
    const countryName = properties.ADMIN;

    // If clicking same country, just open panel
    if (selectedCountry === countryName && culturalData) {
      setIsPanelOpen(true);
      return;
    }

    setSelectedCountry(countryName);
    setIsPanelOpen(true);
    setCulturalData(null);
    setIsLoading(true);

    try {
      const data = await fetchCountryData(countryName);
      setCulturalData(data);
    } catch (error) {
      console.error("Error in app flow:", error);
    } finally {
      setIsLoading(false);
    }
  }, [selectedCountry, culturalData]);

  const closePanel = () => setIsPanelOpen(false);

  return (
    <div className="relative w-full h-screen bg-black overflow-hidden">

      {/* 3D Map Layer */}
      <div className="absolute inset-0 z-0">
        <EarthGlobe onCountryClick={handleCountryClick} />
      </div>

      {/* Overlay UI - Title */}
      <div className="absolute top-6 left-6 z-10 pointer-events-none">
        <div className="flex items-center space-x-3">
          <div className="p-3 bg-blue-600/20 backdrop-blur-md rounded-xl border border-blue-500/30">
            <Music2 className="text-blue-400 w-8 h-8" />
          </div>
          <div>
            <h1 className="text-3xl font-bold text-white tracking-tight drop-shadow-md">
              Terra<span className="text-blue-400">Musica</span>
            </h1>
            <p className="text-blue-200/60 text-sm font-light tracking-widest uppercase">
              Explorador Cultural 3D
            </p>
          </div>
        </div>
      </div>

      {/* Overlay UI - Instructions */}
      {!isPanelOpen && !selectedCountry && (
        <div className="absolute bottom-10 left-1/2 transform -translate-x-1/2 z-10 pointer-events-none text-center">
          <p className="text-white/50 text-sm bg-black/40 backdrop-blur-sm px-4 py-2 rounded-full border border-white/10 animate-pulse">
            Haz clic en un país para descubrir su música
          </p>
        </div>
      )}

      {/* Info Panel Sidebar */}
      <InfoPanel 
        isOpen={isPanelOpen}
        onClose={closePanel}
        isLoading={isLoading}
        data={culturalData}
        selectedCountryName={selectedCountry}
      />

    </div>
  );
};

export default App;

