import React, { useEffect, useRef, useState, useCallback } from 'react';
import Globe, { GlobeMethods } from 'react-globe.gl';
import { GeoJsonProperties } from '../types';

interface EarthGlobeProps {
  onCountryClick: (properties: GeoJsonProperties) => void;
}

export const EarthGlobe: React.FC<EarthGlobeProps> = ({ onCountryClick }) => {
  const globeEl = useRef<GlobeMethods | undefined>(undefined);
  const [hoverD, setHoverD] = useState<object | null>(null);
  const [countries, setCountries] = useState({ features: [] });
  const [width, setWidth] = useState(window.innerWidth);
  const [height, setHeight] = useState(window.innerHeight);

  useEffect(() => {
    // Responsive globe
    const handleResize = () => {
      setWidth(window.innerWidth);
      setHeight(window.innerHeight);
    };
    window.addEventListener('resize', handleResize);

    // Load GeoJSON data
    fetch('https://raw.githubusercontent.com/vasturiano/react-globe.gl/master/example/datasets/ne_110m_admin_0_countries.geojson')
      .then(res => res.json())
      .then(setCountries)
      .catch(err => console.error("Error loading globe data:", err));

    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // Set initial point of view
  useEffect(() => {
    if (globeEl.current) {
      globeEl.current.pointOfView({ lat: 20, lng: 0, altitude: 2.0 });
      // Auto-rotate
      globeEl.current.controls().autoRotate = true;
      globeEl.current.controls().autoRotateSpeed = 0.5;
    }
  }, [globeEl.current]);

  const handlePolygonClick = useCallback((polygon: object) => {
    const p = polygon as { properties: GeoJsonProperties, bbox?: number[] };

    // Stop rotation on interaction
    if (globeEl.current) {
        globeEl.current.controls().autoRotate = false;
    }

    onCountryClick(p.properties);
  }, [onCountryClick]);

  return (
    <div className="cursor-move">
      <Globe
        ref={globeEl}
        width={width}
        height={height}
        globeImageUrl="//unpkg.com/three-globe/example/img/earth-blue-marble.jpg"
        backgroundImageUrl="//unpkg.com/three-globe/example/img/night-sky.png"

        polygonsData={countries.features}
        // Increased altitude for hover to make it "pop" more
        polygonAltitude={d => d === hoverD ? 0.15 : 0.01}
        // Pop Art colors: Cyan hover, transparent default
        polygonCapColor={d => d === hoverD ? 'rgba(84, 198, 235, 0.9)' : 'rgba(200, 200, 200, 0.0)'}
        polygonSideColor={() => 'rgba(255, 255, 255, 0.5)'}
        polygonStrokeColor={() => 'rgba(255, 255, 255, 0.3)'}

        polygonLabel={({ properties: d }: any) => `
          <div style="
            background: #FFD23F; 
            color: black; 
            padding: 4px 8px; 
            border-radius: 4px; 
            font-family: sans-serif; 
            font-weight: bold; 
            border: 2px solid black;
            box-shadow: 3px 3px 0px black;
          ">
            ${d.ADMIN}
          </div>
        `}
        onPolygonHover={setHoverD}
        onPolygonClick={handlePolygonClick}

        atmosphereColor="#3a228a"
        atmosphereAltitude={0.2}
      />
    </div>
  );
};

import React, { useEffect, useRef, useState, useCallback } from 'react';
import Globe, { GlobeMethods } from 'react-globe.gl';
import { GeoJsonProperties } from '../types';
import * as THREE from 'three';

interface EarthGlobeProps {
  onCountryClick: (properties: GeoJsonProperties) => void;
}

export const EarthGlobe: React.FC<EarthGlobeProps> = ({ onCountryClick }) => {
  const globeEl = useRef<GlobeMethods | undefined>(undefined);
  const [hoverD, setHoverD] = useState<object | null>(null);
  const [countries, setCountries] = useState({ features: [] });
  const [width, setWidth] = useState(window.innerWidth);
  const [height, setHeight] = useState(window.innerHeight);

  useEffect(() => {
    const handleResize = () => {
      setWidth(window.innerWidth);
      setHeight(window.innerHeight);
    };
    window.addEventListener('resize', handleResize);

    fetch('https://raw.githubusercontent.com/vasturiano/react-globe.gl/master/example/datasets/ne_110m_admin_0_countries.geojson')
      .then(res => res.json())
      .then(setCountries)
      .catch(err => console.error("Error loading globe data:", err));

    return () => window.removeEventListener('resize', handleResize);
  }, []);

  useEffect(() => {
    if (globeEl.current) {
      globeEl.current.pointOfView({ lat: 20, lng: 0, altitude: 2.0 });
      globeEl.current.controls().autoRotate = true;
      globeEl.current.controls().autoRotateSpeed = 0.8;

      // Set directional light to create hard shadows (cartoonish lighting)
      const directionalLight = globeEl.current.scene().children.find(obj => obj.type === 'DirectionalLight') as THREE.DirectionalLight;
      if (directionalLight) {
        directionalLight.intensity = 1.5;
        directionalLight.position.set(1, 1, 1);
      }
      const ambientLight = globeEl.current.scene().children.find(obj => obj.type === 'AmbientLight') as THREE.AmbientLight;
      if (ambientLight) {
        ambientLight.intensity = 1;
      }
    }
  }, []);

  const handlePolygonClick = useCallback((polygon: object) => {
    const p = polygon as { properties: GeoJsonProperties, bbox?: number[] };
    if (globeEl.current) {
        globeEl.current.controls().autoRotate = false;
    }
    onCountryClick(p.properties);
  }, [onCountryClick]);

  return (
    <div className="cursor-move">
      <Globe
        ref={globeEl}
        width={width}
        height={height}
        backgroundColor="rgba(0,0,0,0)" // Transparent to show the CSS dot pattern

        // --- TOON STYLE SETTINGS ---
        // Use a solid material for the "Ocean"
        globeMaterial={new THREE.MeshPhongMaterial({
          color: '#54C6EB', // Cyan Ocean
          specular: '#ffffff',
          shininess: 5,
        })}
        showAtmosphere={false} // Remove realistic atmosphere haze

        // --- POLYGONS (COUNTRIES) ---
        polygonsData={countries.features}
        // Elevation: Hovered pops up significantly
        polygonAltitude={d => d === hoverD ? 0.15 : 0.02}

        // Colors
        // Default Land: White
        // Hover Land: Yellow Pop
        polygonCapColor={d => d === hoverD ? '#FFD23F' : '#FFFFFF'}

        // Sides of the extrusion (makes it look like a block)
        polygonSideColor={() => '#000000'} 

        // Borders
        polygonStrokeColor={() => '#000000'}

        polygonLabel={({ properties: d }: any) => `
          <div style="
            background: #fff; 
            color: black; 
            padding: 8px 12px; 
            border-radius: 8px; 
            font-family: 'Public Sans', sans-serif; 
            font-weight: 900; 
            text-transform: uppercase;
            border: 3px solid black;
            box-shadow: 4px 4px 0px 0px black;
            transform: translateY(-20px);
          ">
            ${d.ADMIN}
          </div>
        `}
        onPolygonHover={setHoverD}
        onPolygonClick={handlePolygonClick}
      />
    </div>
  );
};

