import { GoogleGenAI, Type, Schema } from "@google/genai";
import { CulturalData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

const schema: Schema = {
  type: Type.OBJECT,
  properties: {
    countryName: { type: Type.STRING },
    summary: { type: Type.STRING, description: "Resumen cultural enfocado en la identidad sonora." },
    traditions: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "3 tradiciones clave."
    },
    musicalStyles: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "Géneros nativos."
    },
    modernInfluentialArtists: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING },
          genre: { type: Type.STRING },
          relevance: { type: Type.STRING, description: "Por qué es relevante hoy." }
        },
        required: ["name", "genre", "relevance"]
      },
      description: "3 artistas contemporáneos más escuchados o influyentes actualmente."
    },
    sampleOrigins: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          description: { type: Type.STRING, description: "Descripción del ritmo, instrumento o canción original que ha sido sampleada." },
          famousUsage: { type: Type.STRING, description: "Canción internacional famosa o género que usó este sample/ritmo (ej: 'Usado en X canción de Drake')." }
        },
        required: ["description", "famousUsage"]
      },
      description: "2 datos curiosos sobre samples o cómo la música de este país influenció hits mundiales (Musical DNA)."
    },
    songs: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          artist: { type: Type.STRING },
          genre: { type: Type.STRING },
          description: { type: Type.STRING },
          youtubeQuery: { type: Type.STRING }
        },
        required: ["title", "artist", "genre", "description", "youtubeQuery"]
      },
      description: "3 canciones esenciales."
    }
  },
  required: ["countryName", "summary", "traditions", "musicalStyles", "modernInfluentialArtists", "sampleOrigins", "songs"]
};

export const fetchCountryData = async (countryName: string): Promise<CulturalData | null> => {
  try {
    const model = "gemini-3-flash-preview";
    const prompt = `
      Analiza la cultura musical de: "${countryName}".

      Necesito un perfil moderno que cubra:
      1. Raíces históricas.
      2. La escena actual (artistas top de hoy).
      3. "ADN Musical": ¿Qué ritmos o canciones de este país han sido sampleados en hits mundiales? O ¿Cómo ha influenciado a otros géneros?

      Responde en JSON válido (Español).
    `;

    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: schema,
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as CulturalData;
    }

    return null;
  } catch (error) {
    console.error("Error fetching data from Gemini:", error);
    return null;
  }
};

