import { GoogleGenAI, Type, Schema } from "@google/genai";
import { CulturalData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

const schema: Schema = {
  type: Type.OBJECT,
  properties: {
    countryName: { type: Type.STRING },
    summary: { type: Type.STRING, description: "Análisis musicológico profundo sobre la identidad sonora y su evolución histórica." },
    traditions: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "3 tradiciones musicales detalladas."
    },
    musicalStyles: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "Géneros nativos y fusiones."
    },
    instruments: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "Instrumentos autóctonos clave."
    },
    curiosities: {
      type: Type.ARRAY,
      items: { type: Type.STRING },
      description: "4 datos curiosos sorprendentes, rarezas musicales o hechos poco conocidos."
    },
    modernInfluentialArtists: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING },
          genre: { type: Type.STRING },
          relevance: { type: Type.STRING, description: "Análisis de su impacto actual." }
        },
        required: ["name", "genre", "relevance"]
      },
      description: "3 artistas contemporáneos que definen la escena hoy."
    },
    sampleOrigins: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          description: { type: Type.STRING, description: "Detalle del ritmo/canción original." },
          famousUsage: { type: Type.STRING, description: "Hit global que lo utilizó." }
        },
        required: ["description", "famousUsage"]
      },
      description: "Conexiones globales: samples o influencias directas en el pop/hip-hop mundial."
    },
    songs: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          artist: { type: Type.STRING },
          genre: { type: Type.STRING },
          description: { type: Type.STRING, description: "Por qué esta canción es esencial." },
          youtubeQuery: { type: Type.STRING }
        },
        required: ["title", "artist", "genre", "description", "youtubeQuery"]
      },
      description: "3 canciones imprescindibles para entender el país."
    }
  },
  required: ["countryName", "summary", "traditions", "musicalStyles", "instruments", "curiosities", "modernInfluentialArtists", "sampleOrigins", "songs"]
};

export const fetchCountryData = async (countryName: string): Promise<CulturalData | null> => {
  try {
    const model = "gemini-3-flash-preview";
    const prompt = `
      Actúa como un etnomusicólogo experto y curador musical moderno. Analiza: "${countryName}".

      Quiero información PROFUNDA y no genérica. Evita clichés turísticos.
      1. Profundidad Histórica: Cómo la historia política/social formó su sonido.
      2. Escena Actual: No solo los más famosos, sino los más innovadores.
      3. Curiosidades: Datos "Mind-blowing" sobre su música.
      4. Conexiones: Cómo este país ha influido en la música global (Samples, ritmos exportados).

      Responde en JSON válido (Español).
    `;

    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: schema,
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as CulturalData;
    }

    return null;
  } catch (error) {
    console.error("Error fetching data from Gemini:", error);
    return null;
  }
};

