export const fetchCountryData = async (countryName: string): Promise<CulturalData | null> => {
  try {
    const model = "gemini-3-flash-preview";
    const prompt = `
      Actúa como un etnomusicólogo experto y crítico musical de Pitchfork. Analiza: "${countryName}".

      Necesito un perfil cultural profundo y también datos de charts:
      1. Historia y raíces profundas.
      2. TOP CHARTS: ¿Qué suena en la radio comercial de ${countryName} hoy? (Simula un Billboard local).
      3. CRITICAL ACCLAIM: ¿Qué álbum indie/alternativo de este país tendría un puntaje alto en Pitchfork?
      4. Curiosidades y samples.

      Responde en JSON válido (Español).
    `;

    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: schema,
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as CulturalData;
    }

    return null;
  } catch (error) {
    console.error("Error fetching data from Gemini:", error);
    return null;
  }
};

