import React, { useState, useCallback } from 'react';
import { EarthGlobe } from './components/EarthGlobe';
import { InfoPanel } from './components/InfoPanel';
import { MusicHud } from './components/MusicHud';
import { fetchCountryData } from './services/geminiService';
import { CulturalData, GeoJsonProperties } from './types';
import { Mic2 } from 'lucide-react';

const App: React.FC = () => {
  const [selectedCountry, setSelectedCountry] = useState<string | null>(null);
  const [culturalData, setCulturalData] = useState<CulturalData | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isPanelOpen, setIsPanelOpen] = useState(false);

  const handleCountryClick = useCallback(async (properties: GeoJsonProperties) => {
    const countryName = properties.ADMIN;

    // Always open panel and load data if clicking a country
    setSelectedCountry(countryName);
    setIsPanelOpen(true);

    // Only fetch if data isn't already there for this country
    if (selectedCountry !== countryName || !culturalData) {
        setCulturalData(null);
        setIsLoading(true);
        try {
            const data = await fetchCountryData(countryName);
            setCulturalData(data);
        } catch (error) {
            console.error("Error in app flow:", error);
        } finally {
            setIsLoading(false);
        }
    }
  }, [selectedCountry, culturalData]);

  const closePanel = () => setIsPanelOpen(false);

  return (
    <div className="relative w-full h-screen overflow-hidden font-sans bg-[#0A0A0A]">
      {/* Background Texture Div */}
      <div className="bg-texture"></div>

      {/* 3D Map Layer */}
      <div className="absolute inset-0 z-0">
        <EarthGlobe onCountryClick={handleCountryClick} />
      </div>

      {/* Overlay UI - Minimal Title (Top Left) */}
      <div className="absolute top-8 left-8 z-20 pointer-events-none">
         <div className="flex items-start gap-3">
            <div className="bg-white text-black p-3 rounded-2xl shadow-[0_0_15px_rgba(255,255,255,0.2)]">
               <Mic2 size={24} />
            </div>
            <div className="bg-[#111]/80 backdrop-blur-md px-6 py-3 rounded-2xl border border-white/10 shadow-xl">
               <h1 className="text-2xl font-bold text-white tracking-tight">TerraMusica</h1>
               <p className="text-xs text-[#B4E197] font-bold uppercase tracking-wider mt-1">
                 Dark Edition
               </p>
            </div>
         </div>
      </div>

      {/* Music HUD (Billboard Bottom-Left, Pitchfork Top-Right) */}
      {/* We hide the HUD if loading, or if no data. 
          Note: The Pitchfork widget sits top-right. The Panel sits right.
          The Panel z-index is 50, HUD is 30. Panel will cover HUD when open on small screens,
          but on large screens they might overlap visually.
      */}
      <MusicHud 
        data={culturalData} 
        isVisible={!isLoading && culturalData !== null} 
      />

      {/* Helper Pill */}
      {!isPanelOpen && !selectedCountry && (
        <div className="absolute bottom-12 left-1/2 transform -translate-x-1/2 z-10 pointer-events-none">
          <div className="bg-[#1E1E1E] text-white px-6 py-3 rounded-full shadow-2xl border border-white/10 flex items-center gap-2 animate-bounce">
            <span className="w-2 h-2 bg-[#B4E197] rounded-full shadow-[0_0_8px_#B4E197]"></span>
            <span className="text-sm font-medium">Explora el mapa</span>
          </div>
        </div>
      )}

      {/* Info Panel Sidebar */}
      <InfoPanel 
        isOpen={isPanelOpen}
        onClose={closePanel}
        isLoading={isLoading}
        data={culturalData}
        selectedCountryName={selectedCountry}
      />

    </div>
  );
};

