import React, { useState, useCallback } from 'react';
import { EarthGlobe } from './components/EarthGlobe';
import { InfoPanel } from './components/InfoPanel';
import { MusicHud } from './components/MusicHud';
import { fetchCountryData } from './services/geminiService';
import { CulturalData, GeoJsonProperties } from './types';
import { Mic2, Radio, BookOpen } from 'lucide-react';

const App: React.FC = () => {
  const [selectedCountry, setSelectedCountry] = useState<string | null>(null);
  const [culturalData, setCulturalData] = useState<CulturalData | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isPanelOpen, setIsPanelOpen] = useState(false);

  // New State for Mode: 'mainstream' (Charts/Pop) vs 'editorial' (Pitchfork/Indie)
  const [appMode, setAppMode] = useState<'mainstream' | 'editorial'>('mainstream');

  const handleCountryClick = useCallback(async (properties: GeoJsonProperties) => {
    const countryName = properties.ADMIN;

    setSelectedCountry(countryName);
    setIsPanelOpen(true);

    if (selectedCountry !== countryName || !culturalData) {
        setCulturalData(null);
        setIsLoading(true);
        try {
            // We fetch everything at once now
            const data = await fetchCountryData(countryName);
            setCulturalData(data);
        } catch (error) {
            console.error("Error in app flow:", error);
        } finally {
            setIsLoading(false);
        }
    }
  }, [selectedCountry, culturalData]);

  const closePanel = () => setIsPanelOpen(false);

  return (
    <div className={`relative w-full h-screen overflow-hidden font-sans transition-colors duration-700 
      ${appMode === 'editorial' ? 'bg-[#000000]' : 'bg-[#0A0A0A]'}`}>

      {/* Background Texture Div */}
      <div className="bg-texture"></div>

      {/* 3D Map Layer */}
      <div className="absolute inset-0 z-0">
        <EarthGlobe onCountryClick={handleCountryClick} />
      </div>

      {/* HEADER AREA */}
      <div className="absolute top-8 left-8 z-20 flex flex-col gap-4 pointer-events-none">
         {/* Logo Block */}
         <div className="flex items-start gap-3 pointer-events-auto">
            <div className={`p-3 rounded-2xl shadow-lg transition-colors duration-500 
              ${appMode === 'editorial' ? 'bg-[#FF3530] text-black rounded-none' : 'bg-white text-black rounded-2xl'}`}>
               <Mic2 size={24} />
            </div>
            <div className={`backdrop-blur-md px-6 py-3 border shadow-xl transition-all duration-500
               ${appMode === 'editorial' ? 'bg-black/90 border-[#333] rounded-none' : 'bg-[#111]/80 border-white/10 rounded-2xl'}`}>
               <h1 className={`text-2xl font-bold tracking-tight transition-colors 
                 ${appMode === 'editorial' ? 'text-white font-serif-display italic' : 'text-white font-sans'}`}>
                 TerraMusica
               </h1>
               <p className={`text-xs font-bold uppercase tracking-wider mt-1 transition-colors
                 ${appMode === 'editorial' ? 'text-[#FF3530]' : 'text-[#B4E197]'}`}>
                 {appMode === 'editorial' ? 'Alternative Issue' : 'Dark Edition'}
               </p>
            </div>
         </div>

         {/* MODE TOGGLE SWITCH (Pointer Events Auto) */}
         <div className="bg-black/80 backdrop-blur-md p-1.5 rounded-xl border border-white/10 inline-flex items-center gap-1 shadow-2xl pointer-events-auto w-fit">
            <button 
              onClick={() => setAppMode('mainstream')}
              className={`px-4 py-2 rounded-lg text-xs font-bold uppercase tracking-wide flex items-center gap-2 transition-all
                ${appMode === 'mainstream' 
                  ? 'bg-[#B4E197] text-black shadow-sm' 
                  : 'text-gray-500 hover:text-white hover:bg-white/5'}`}
            >
              <Radio size={14} /> Mainstream
            </button>
            <button 
              onClick={() => setAppMode('editorial')}
              className={`px-4 py-2 rounded-lg text-xs font-bold uppercase tracking-wide flex items-center gap-2 transition-all
                ${appMode === 'editorial' 
                  ? 'bg-[#FF3530] text-black shadow-sm' 
                  : 'text-gray-500 hover:text-white hover:bg-white/5'}`}
            >
              <BookOpen size={14} /> Editorial
            </button>
         </div>
      </div>

      {/* Music HUD */}
      <MusicHud 
        data={culturalData} 
        isVisible={!isLoading && culturalData !== null} 
        mode={appMode}
      />

      {/* Info Panel Sidebar */}
      <InfoPanel 
        isOpen={isPanelOpen}
        onClose={closePanel}
        isLoading={isLoading}
        data={culturalData}
        selectedCountryName={selectedCountry}
        mode={appMode}
      />

    </div>
  );
};

export default App;

