export const fetchCountryData = async (countryName: string): Promise<CulturalData | null> => {
  try {
    const model = "gemini-3-flash-preview";
    const prompt = `
      Actúa como el editor en jefe de Pitchfork, NME y un sociólogo musical. Analiza: "${countryName}".

      Dame dos perspectivas en un solo JSON:
      1. MAINSTREAM: Lo que suena en la radio (Charts, Historia general).
      2. EDITORIAL/UNDERGROUND: Un "Special Issue" de revista sobre la escena alternativa, experimental y de culto.

      Sé específico, intelectual, un poco pretencioso pero informativo.
      Responde en JSON válido (Español).
    `;

    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: schema,
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as CulturalData;
    }

    return null;
  } catch (error) {
    console.error("Error fetching data from Gemini:", error);
    return null;
  }
};

