import React, { useState } from "react";
import { ComposableMap, Geographies, Geography, ZoomableGroup } from "react-simple-maps";
import { GeoJsonProperties } from "../types";

const geoUrl = "https://cdn.jsdelivr.net/npm/world-atlas@2/countries-110m.json";

interface FlatMapProps {
  onCountryClick: (properties: GeoJsonProperties) => void;
  selectedCountry: string | null;
}

export const FlatMap: React.FC<FlatMapProps> = ({ onCountryClick, selectedCountry }) => {
  const [position, setPosition] = useState({ coordinates: [0, 0], zoom: 1 });

  return (
    <div className="w-full h-full bg-[#EAEAEA] transition-colors duration-1000">
      <ComposableMap
        projectionConfig={{
          scale: 160,
          rotation: [-11, 0, 0],
        }}
        width={800}
        height={500}
        style={{ width: "100%", height: "100%" }}
      >
        <ZoomableGroup
          zoom={position.zoom}
          center={position.coordinates as [number, number]}
          onMoveEnd={((position) => setPosition(position))}
          minZoom={0.7}
          maxZoom={8}
        >
          <Geographies geography={geoUrl}>
            {({ geographies }) =>
              geographies.map((geo) => {
                 const isSelected = selectedCountry === geo.properties.name;

                 return (
                  <Geography
                    key={geo.rsmKey}
                    geography={geo}
                    onClick={() => {
                        onCountryClick({
                            ADMIN: geo.properties.name,
                            ISO_A3: geo.id
                        });
                    }}
                    style={{
                      default: {
                        fill: isSelected ? "#FF3530" : "#D1D1D1",
                        stroke: "#EAEAEA",
                        strokeWidth: 0.5,
                        outline: "none",
                        transition: "all 250ms"
                      },
                      hover: {
                        fill: "#333",
                        stroke: "#EAEAEA",
                        strokeWidth: 0.5,
                        outline: "none",
                        cursor: "pointer"
                      },
                      pressed: {
                        fill: "#000",
                        stroke: "#EAEAEA",
                        strokeWidth: 0.5,
                        outline: "none",
                      },
                    }}
                  />
                );
              })
            }
          </Geographies>
        </ZoomableGroup>
      </ComposableMap>

      {/* Editorial Decorative Elements */}
      <div className="absolute bottom-12 left-12 font-serif-display text-black/20 text-9xl pointer-events-none select-none italic">
         World<br/>Atlas
      </div>
      <div className="absolute top-12 right-12 w-64 h-px bg-black/10"></div>
      <div className="absolute top-12 right-12 h-64 w-px bg-black/10"></div>
    </div>
  );
};

import React, { useState, useCallback } from 'react';
import { EarthGlobe } from './components/EarthGlobe';
import { FlatMap } from './components/FlatMap';
import { InfoPanel } from './components/InfoPanel';
import { MusicHud } from './components/MusicHud';
import { fetchCountryData } from './services/geminiService';
import { CulturalData, GeoJsonProperties } from './types';
import { Mic2, Radio, BookOpen } from 'lucide-react';

const App: React.FC = () => {
  const [selectedCountry, setSelectedCountry] = useState<string | null>(null);
  const [culturalData, setCulturalData] = useState<CulturalData | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isPanelOpen, setIsPanelOpen] = useState(false);

  // New State for Mode: 'mainstream' (Charts/Pop) vs 'editorial' (Pitchfork/Indie)
  const [appMode, setAppMode] = useState<'mainstream' | 'editorial'>('mainstream');

  const handleCountryClick = useCallback(async (properties: GeoJsonProperties) => {
    const countryName = properties.ADMIN;

    setSelectedCountry(countryName);
    setIsPanelOpen(true);

    if (selectedCountry !== countryName || !culturalData) {
        setCulturalData(null);
        setIsLoading(true);
        try {
            const data = await fetchCountryData(countryName);
            setCulturalData(data);
        } catch (error) {
            console.error("Error in app flow:", error);
        } finally {
            setIsLoading(false);
        }
    }
  }, [selectedCountry, culturalData]);

  const closePanel = () => setIsPanelOpen(false);

  return (
    <div className={`relative w-full h-screen overflow-hidden font-sans transition-colors duration-1000 
      ${appMode === 'editorial' ? 'bg-[#EAEAEA]' : 'bg-[#0A0A0A]'}`}>

      {/* Background Texture Div */}
      <div className={`bg-texture transition-opacity duration-1000 ${appMode === 'editorial' ? 'opacity-20' : 'opacity-5'}`}></div>

      {/* MAP LAYERS SWITCHER */}
      <div className="absolute inset-0 z-0 transition-opacity duration-1000">
        {appMode === 'mainstream' ? (
           <EarthGlobe onCountryClick={handleCountryClick} />
        ) : (
           <FlatMap onCountryClick={handleCountryClick} selectedCountry={selectedCountry} />
        )}
      </div>

      {/* HEADER AREA */}
      <div className="absolute top-8 left-8 z-20 flex flex-col gap-4 pointer-events-none">
         {/* Logo Block */}
         <div className="flex items-start gap-3 pointer-events-auto">
            <div className={`p-3 rounded-2xl shadow-lg transition-colors duration-500 
              ${appMode === 'editorial' ? 'bg-[#FF3530] text-black rounded-none shadow-none' : 'bg-white text-black rounded-2xl'}`}>
               <Mic2 size={24} />
            </div>
            <div className={`backdrop-blur-md px-6 py-3 border shadow-xl transition-all duration-500
               ${appMode === 'editorial' ? 'bg-white border-black/10 rounded-none shadow-sm' : 'bg-[#111]/80 border-white/10 rounded-2xl'}`}>
               <h1 className={`text-2xl font-bold tracking-tight transition-colors 
                 ${appMode === 'editorial' ? 'text-black font-cinzel tracking-wider' : 'text-white font-sans'}`}>
                 TerraMusica
               </h1>
               <p className={`text-xs font-bold uppercase tracking-wider mt-1 transition-colors
                 ${appMode === 'editorial' ? 'text-[#FF3530]' : 'text-[#B4E197]'}`}>
                 {appMode === 'editorial' ? 'Volume 04: The World' : 'Dark Edition'}
               </p>
            </div>
         </div>

         {/* MODE TOGGLE SWITCH (Pointer Events Auto) */}
         <div className={`backdrop-blur-md p-1.5 border inline-flex items-center gap-1 shadow-2xl pointer-events-auto w-fit transition-all duration-500
             ${appMode === 'editorial' ? 'bg-white border-black/10 rounded-none' : 'bg-black/80 border-white/10 rounded-xl'}`}>
            <button 
              onClick={() => setAppMode('mainstream')}
              className={`px-4 py-2 text-xs font-bold uppercase tracking-wide flex items-center gap-2 transition-all
                ${appMode === 'mainstream' 
                  ? 'bg-[#B4E197] text-black shadow-sm rounded-lg' 
                  : 'text-gray-500 hover:text-black hover:bg-black/5'}`}
            >
              <Radio size={14} /> Mainstream
            </button>
            <button 
              onClick={() => setAppMode('editorial')}
              className={`px-4 py-2 text-xs font-bold uppercase tracking-wide flex items-center gap-2 transition-all
                ${appMode === 'editorial' 
                  ? 'bg-[#FF3530] text-white shadow-sm' 
                  : 'text-gray-500 hover:text-black hover:bg-black/5'}`}
            >
              <BookOpen size={14} /> Editorial
            </button>
         </div>
      </div>

      {/* Music HUD */}
      <MusicHud 
        data={culturalData} 
        isVisible={!isLoading && culturalData !== null} 
        mode={appMode}
      />

      {/* Info Panel Sidebar */}
      <InfoPanel 
        isOpen={isPanelOpen}
        onClose={closePanel}
        isLoading={isLoading}
        data={culturalData}
        selectedCountryName={selectedCountry}
        mode={appMode}
      />

    </div>
  );
};

export default App;

