export const fetchCountryData = async (countryName: string): Promise<CulturalData | null> => {
  try {
    const model = "gemini-3-flash-preview";
    const prompt = `
      Analiza profundamente la cultura musical de: "${countryName}".

      ADOPTA UNA PERSONALIDAD EDITORIAL ESPECÍFICA SEGÚN LA REGIÓN:
      - Si es LATINOAMÉRICA: Escribe como **Indie Hoy / Remezcla**. Enfócate en la fusión de folclore con electrónica, activismo y la escena urbana experimental.
      - Si es ASIA (Japón/China/Corea): Escribe como **Ele-King / Neocha / Douban Music**. Enfócate en lo visual, moda, noise, city pop revival y underground clubes.
      - Si es EUROPA/UK: Escribe como **The Quietus / The Wire**. Sé intelectual, oscuro, habla de post-punk, techno industrial y vanguardia.
      - Si es USA/Global: Escribe como **Pitchfork / The FADER**. Usa términos como "Best New Music", enfócate en la producción y la narrativa del artista.

      GENERA UN JSON (Español):
      1. MAINSTREAM: Datos generales.
      2. EDITORIAL: 
         - 'magazineStyle': Indica qué estilo adoptaste (ej: "Estilo Remezcla").
         - 'longFormEssay': Ensayo sofisticado (4 párrafos) conectando política, sociedad y música.
         - 'recordStores': Tiendas de vinilos reales y específicas o venues de culto.
         - 'criticalPick': Un álbum clásico moderno o joya oculta. Si es muy bueno, pon score > 8.0 y isBestNewMusic: true.
         - 'visualAesthetic': Describe cómo se VISTE la escena (moda, colores, tribus urbanas).
         - 'sonicSignature': DECONSTRUYE EL SONIDO. 
            * instruments: Instrumentos específicos (ej: 'Sintetizadores modulares', 'Guzheng procesado', '808s distorsionados').
            * vocals: Estilo vocal (ej: 'Falsetto etéreo', 'Auto-tune agresivo', 'Spoken word político').
            * production: Técnicas de estudio (ej: 'Lo-fi tape saturation', 'Reverb catedralicio', 'Sampleo de jazz').
         - 'localVerdict': Usa una plataforma local (ej: Douban para China, RateYourMusic para Occidente) y da un puntaje/consenso.

      Responde en JSON válido.
    `;

    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: schema,
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as CulturalData;
    }

    return null;
  } catch (error) {
    console.error("Error fetching data from Gemini:", error);
    return null;
  }
};

import React, { useState, useCallback } from 'react';
import { EarthGlobe } from './components/EarthGlobe';
import { FlatMap } from './components/FlatMap';
import { InfoPanel } from './components/InfoPanel';
import { MusicHud } from './components/MusicHud';
import { fetchCountryData } from './services/geminiService';
import { CulturalData, GeoJsonProperties } from './types';
import { Mic2, Radio, BookOpen } from 'lucide-react';

const App: React.FC = () => {
  const [selectedCountry, setSelectedCountry] = useState<string | null>(null);
  const [culturalData, setCulturalData] = useState<CulturalData | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isPanelOpen, setIsPanelOpen] = useState(false);

  // New State for Mode: 'mainstream' (Charts/Pop) vs 'editorial' (Pitchfork/Indie)
  const [appMode, setAppMode] = useState<'mainstream' | 'editorial'>('mainstream');

  const handleCountryClick = useCallback(async (properties: GeoJsonProperties) => {
    const countryName = properties.ADMIN;

    setSelectedCountry(countryName);
    setIsPanelOpen(true);

    if (selectedCountry !== countryName || !culturalData) {
        setCulturalData(null);
        setIsLoading(true);
        try {
            const data = await fetchCountryData(countryName);
            setCulturalData(data);
        } catch (error) {
            console.error("Error in app flow:", error);
        } finally {
            setIsLoading(false);
        }
    }
  }, [selectedCountry, culturalData]);

  const closePanel = () => setIsPanelOpen(false);

  return (
    <div className="relative w-full h-screen overflow-hidden font-sans transition-colors duration-1000 bg-[#050505]">

      {/* Background Texture Div - Always dark but texture changes slightly */}
      <div className="bg-texture opacity-10 fixed inset-0 pointer-events-none mix-blend-overlay"></div>

      {/* MAP LAYERS SWITCHER */}
      <div className="absolute inset-0 z-0 transition-opacity duration-1000">
        {appMode === 'mainstream' ? (
           <EarthGlobe onCountryClick={handleCountryClick} />
        ) : (
           <FlatMap onCountryClick={handleCountryClick} selectedCountry={selectedCountry} />
        )}
      </div>

      {/* HEADER AREA */}
      <div className="absolute top-8 left-8 z-20 flex flex-col gap-4 pointer-events-none">
         {/* Logo Block */}
         <div className="flex items-start gap-3 pointer-events-auto">
            <div className={`p-3 rounded-2xl shadow-lg transition-colors duration-500 
              ${appMode === 'editorial' ? 'bg-[#FF3530] text-black rounded-none shadow-none' : 'bg-white text-black rounded-2xl'}`}>
               <Mic2 size={24} />
            </div>
            <div className={`backdrop-blur-md px-6 py-3 border shadow-xl transition-all duration-500
               ${appMode === 'editorial' ? 'bg-black border-white/20 rounded-none shadow-sm' : 'bg-[#111]/80 border-white/10 rounded-2xl'}`}>
               <h1 className={`text-2xl font-bold tracking-tight transition-colors 
                 ${appMode === 'editorial' ? 'text-white font-cinzel tracking-wider' : 'text-white font-sans'}`}>
                 TerraMusica
               </h1>
               <p className={`text-xs font-bold uppercase tracking-wider mt-1 transition-colors
                 ${appMode === 'editorial' ? 'text-[#FF3530]' : 'text-[#B4E197]'}`}>
                 {appMode === 'editorial' ? 'Volume 04: The World' : 'Dark Edition'}
               </p>
            </div>
         </div>

         {/* MODE TOGGLE SWITCH (Pointer Events Auto) */}
         <div className={`backdrop-blur-md p-1.5 border inline-flex items-center gap-1 shadow-2xl pointer-events-auto w-fit transition-all duration-500
             ${appMode === 'editorial' ? 'bg-black border-white/20 rounded-none' : 'bg-black/80 border-white/10 rounded-xl'}`}>
            <button 
              onClick={() => setAppMode('mainstream')}
              className={`px-4 py-2 text-xs font-bold uppercase tracking-wide flex items-center gap-2 transition-all
                ${appMode === 'mainstream' 
                  ? 'bg-[#B4E197] text-black shadow-sm rounded-lg' 
                  : 'text-gray-500 hover:text-white hover:bg-white/5'}`}
            >
              <Radio size={14} /> Mainstream
            </button>
            <button 
              onClick={() => setAppMode('editorial')}
              className={`px-4 py-2 text-xs font-bold uppercase tracking-wide flex items-center gap-2 transition-all
                ${appMode === 'editorial' 
                  ? 'bg-[#FF3530] text-white shadow-sm' 
                  : 'text-gray-500 hover:text-white hover:bg-white/5'}`}
            >
              <BookOpen size={14} /> Editorial
            </button>
         </div>
      </div>

      {/* Music HUD */}
      <MusicHud 
        data={culturalData} 
        isVisible={!isLoading && culturalData !== null} 
        mode={appMode}
      />

      {/* Info Panel Sidebar */}
      <InfoPanel 
        isOpen={isPanelOpen}
        onClose={closePanel}
        isLoading={isLoading}
        data={culturalData}
        selectedCountryName={selectedCountry}
        mode={appMode}
      />

    </div>
  );
};

export default App;

