export const fetchCountryData = async (countryName: string): Promise<CulturalData | null> => {
  try {
    const model = "gemini-3-flash-preview";
    const prompt = `
      Analiza profundamente la cultura musical de: "${countryName}".

      ADOPTA UNA PERSONALIDAD EDITORIAL SEGÚN REGIÓN (Indie Hoy/Remezcla, Ele-King, The Quietus, Pitchfork).

      GENERA UN JSON (Español) con esta estructura:
      1. MAINSTREAM: Datos generales.
      2. EDITORIAL: 
         - 'editorialChapters': Genera 3 CAPÍTULOS DISTINTOS para un artículo de fondo.
           * Cap 1: "Raíces y Ruido" (Historia underground)
           * Cap 2: "La Escena Hoy" (Colectivos actuales)
           * Cap 3: "Futuros Posibles" (Hacia dónde va)
         - 'cultAlbums': 3 Álbumes de culto imprescindibles.
           * albumName, artist, year, label
           * reason: Por qué es influyente (breve)
         - 'curatedReads': 4 Artículos para profundizar.
           * title: Título atractivo (ej: "How [Artist] Changed [Genre]").
           * source: Medio (Pitchfork, Resident Advisor, etc).
           * url: Link REAL si es posible, o un link de búsqueda de Google bien formado (ej: "https://www.google.com/search?q=...").

         ... resto de campos igual (sonicSignature, recordStores, playlist).

      Responde en JSON válido.
    `;

    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: schema,
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as CulturalData;
    }

    return null;
  } catch (error) {
    console.error("Error fetching data from Gemini:", error);
    return null;
  }
};

