export const fetchCountryData = async (countryName: string): Promise<CulturalData | null> => {
  try {
    const model = "gemini-3-flash-preview";
    const prompt = `
      Analiza profundamente la cultura musical de: "${countryName}".

      ADOPTA UNA PERSONALIDAD EDITORIAL SEGÚN REGIÓN (Indie Hoy/Remezcla, Ele-King, The Quietus, Pitchfork).

      GENERA UN JSON (Español) con esta estructura:
      1. MAINSTREAM: Datos generales.
      2. EDITORIAL: 
         - 'editorialChapters': 3 CAPÍTULOS DISTINTOS (Pasado, Presente, Futuro).
         - 'cultAlbums': 3 Álbumes de culto.
           * albumName, artist, year, label
           * coverArtQuery: Query para YouTube/Google (ej: "[Artist] [Album] full album cover art")
         - 'forecast': Sección "Radar 2024-2026".
           * trendName: Nombre cool de la tendencia underground futura (ej: "Neo-Perreo Cyberpunk", "Post-Folk Digital").
           * description: Análisis detallado de lo que se viene (2024-2026). Enfócate en micro-escenas, sellos pequeños y sonidos experimentales.
           * futureSounds: Tags sonoros futuristas.
           * curiosities: Datos random, samples oscuros o conexiones bizarras de esta escena emergente.
         - 'curatedReads': 4 Artículos para profundizar.
           * title: Título atractivo.
           * source: Medio relevante (Vice, The Wire, Pitchfork, Blogs locales).
           * url: No inventes URLs completas. Devuelve solo el dominio (ej: "pitchfork.com") o un string vacío, el frontend construirá la búsqueda.

      Responde en JSON válido.
    `;

    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: schema,
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as CulturalData;
    }

    return null;
  } catch (error) {
    console.error("Error fetching data from Gemini:", error);
    return null;
  }
};

