        mode={appMode}
      />

      {/* Info Panel Sidebar */}
      <InfoPanel 
        isOpen={isPanelOpen}
        onClose={closePanel}
        isLoading={isLoading}
        data={culturalData}
        selectedCountryName={selectedCountry}
        mode={appMode}
      />

    </div>
  );
};

